// Zapamiętaj czas startu i przygotuj listę iteracji.
const startTime = Date.now();
const count = 100;
const iterations = Array.from({ length: count }, (_, index) => index);

return [{ json: { startTime, count, iterations } }];

// Policz czas od startu do zakończenia ostatniej iteracji.
const start = $('Start - czas i lista iteracji').first().json;
const endTime = Date.now();
const totalTimeMs = endTime - start.startTime;
const totalTimeSeconds = totalTimeMs / 1000;

return [{
  json: {
    startTime: start.startTime,
    endTime,
    totalTimeMs,
    totalTimeSeconds,
    message: `Wykonanie ${start.count} zapytań zajęło ${totalTimeSeconds} s`
  }
}];
